mod solution;
fn main() {
    assert_eq!(solution::RetryPolicy::new(0).is_none(), true, "case 1");
    assert_eq!(solution::RetryPolicy::new(1).unwrap().attempts(), 1, "case 2");
    assert_eq!(solution::RetryPolicy::new(255).unwrap().attempts(), 255, "case 3");
    assert_eq!(solution::RetryPolicy::new(2).unwrap().delay_ms(), 0, "case 4");
    assert_eq!(solution::RetryPolicy::new(2).unwrap().with_delay(u32::MAX).delay_ms(), u32::MAX, "case 5");
    assert_eq!(solution::RetryPolicy::new(2).unwrap().with_delay(50).attempts(), 2, "case 6");
    println!("PASS public-api-compatibility");
}
